package com.bank.txnindex;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class IterativeSearchDemo {

    private static final Logger log = Logger.getLogger(IterativeSearchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Sorted ascending — required.
        int[] txnIds = {101, 205, 309, 412, 530, 644, 701, 888};

        TxnIndex index = new TxnIndex();

        int found = index.indexOf(txnIds, 530);
        log.info(() -> "Txn 530 at index: " + found);

        int missing = index.indexOf(txnIds, 600);
        log.info(() -> "Txn 600 at index: " + missing + " (-1 means not processed)");
    }
}

