class TxnIndex {

    private static final Logger log = Logger.getLogger(TxnIndex.class.getName());

    // Iterative binary search: constant space, logarithmic time.
    int indexOf(int[] sorted, int target) {
        int left = 0;
        int right = sorted.length - 1;

        while (left <= right) {                 // range still valid
            int mid = left + (right - left) / 2; // overflow-safe midpoint
            final int l = left, r = right, m = mid;
            log.info(() -> "  left=" + l + " right=" + r + " mid=" + m
                    + " value=" + sorted[m]);

            if (sorted[mid] == target) {
                return mid;                     // found
            } else if (sorted[mid] < target) {
                left = mid + 1;                 // discard left half incl. mid
            } else {
                right = mid - 1;                // discard right half incl. mid
            }
        }
        return -1;                              // left > right → not present
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
